class RedirectView(View):
    http_method_names = ["get", "post", "head", "options"]
    permanent = False
    query_string = False
    url = None
    pattern_name = None
    current_app = None
    preserve_request = False  # Add this line

    def get_redirect_url(self, *args, **kwargs):
        if self.url:
            return self.url % kwargs
        elif self.pattern_name:
            return reverse(
                self.pattern_name,
                args=args,
                kwargs=kwargs,
                current_app=self.current_app,
            )
        else:
            raise ImproperlyConfigured(
                "%(cls)s is missing a URL to redirect to. "
                "Provide either the 'url' or 'pattern_name' attribute."
                % {"cls": self.__class__.__name__}
            )

    def get(self, request, *args, **kwargs):
        url = self.get_redirect_url(*args, **kwargs)
        if self.preserve_request:
            response = HttpResponseRedirect(url)
            for key, value in request.headers.items():
                response["X-Django-Preserve-" + key] = value
            response.content = request.body
            return response
        if self.permanent:
            return HttpResponsePermanentRedirect(url)
        else:
            return HttpResponseRedirect(url)

    def post(self, *args, **kwargs):
        """Handle POST requests: redirect to the same URL."""
        return self.get(*args, **kwargs)

    def head(self, request, *args, **kwargs):
        response = self.get(request, *args, **kwargs)
        response.content = ""
        return response

    @classonlymethod
    def as_view(cls, **initkwargs):
        """Main entry point for a request-response process."""
        initkwargs.setdefault("preserve_request", cls.preserve_request)  # Add this line
        return super().as_view(**initkwargs)
